import type { Register } from "claude-code";
import {
  AgentLoop,
  agentAddress,
  CONFIG_HEADER,
  HEADERS,
  isPortFile,
  type Line,
  PROOF_HEADER,
  pidRuns,
  portTarget,
  signCall,
} from "./agent.ts";
import { Handover } from "./handover.ts";
import { configDir, Poller } from "./poller.ts";
import { Sent, sessionElsewhere } from "./sent.ts";
import { forParent, tagAsk, toSubagents, untagAsk } from "./subagent.ts";
import { Switch, wantsLoop } from "./switch.ts";

/**
 * Starts the answer loop in each session a person keeps open (`wantsLoop`): through the machine's agent when it runs
 * (agent.ts), else through the CLI (poller.ts); switch.ts picks. A hot reload loads this module
 * afresh: the old loop dies with the old module, and `session.start` starts a new one. While the
 * main agent's turn runs, an answer goes out with its next tool result instead (handover.ts).
 * An answer submitted as a prompt stays on record until its turn starts, so a process that exits
 * first does not lose it (sent.ts).
 */
/**
 * Exits 0 when "$1" is a file owned by this user or root that neither its group nor others may
 * write: what `ownedFile` (node.ts) checks, for a host that reads no owner or mode.
 */
const OWNED =
  '[ -n "$(find -L "$1" -prune -type f \\( -user "$(id -u)" -o -user 0 \\) ! -perm -020 ! -perm -002 2>/dev/null)" ]';

export const register: Register = (on) => {
  let loop: Switch | undefined;
  /** Prompts submitted whose turn has not started. */
  let waiting = 0;
  // `$.prompt.submit` resolves when the prompt's turn starts: mid-turn, once the running one ends.
  const track = (submitted: Promise<unknown>) => {
    waiting++;
    const started = () => void waiting--;
    submitted.then(started, started);
    return submitted;
  };
  const handover = new Handover();
  let sent: Sent | undefined;
  /** Answers a subagent could not take: they go to the parent from then on (#1702). */
  const failed = new Set<string>();
  /** When each subagent's last tool call ended: a message sent before then, it has read. */
  const roundEnded = new Map<string, number>();

  on("session.start", async ($, e, next) => {
    handover.ended();
    const started = await next(e);
    if (!wantsLoop(e.isInteractive, await $.env.get("CLAUDE_CODE_ENTRYPOINT"))) return started;
    // The new loop takes over the lines the old one submitted and has not confirmed yet, so it
    // confirms them rather than submitting them again (#1337).
    const before = loop;
    void before?.stop();
    const env = {
      STARBRIDGE_AGENT_SOCKET: await $.env.get("STARBRIDGE_AGENT_SOCKET"),
      STARBRIDGE_CONFIG_DIR: await $.env.get("STARBRIDGE_CONFIG_DIR"),
      STARBRIDGE_NO_AGENT: await $.env.get("STARBRIDGE_NO_AGENT"),
      CLAUDE_CONFIG_DIR: await $.env.get("CLAUDE_CONFIG_DIR"),
      XDG_CONFIG_HOME: await $.env.get("XDG_CONFIG_HOME"),
      XDG_RUNTIME_DIR: await $.env.get("XDG_RUNTIME_DIR"),
      HOME: await $.env.get("HOME"),
      USERPROFILE: await $.env.get("USERPROFILE"),
      OS: await $.env.get("OS"),
    };
    const dir = configDir(env);
    const { socket, config } = await agentAddress(env);
    const base = config ? { ...HEADERS, [CONFIG_HEADER]: config } : HEADERS;
    // Kept across a hot reload, and new in each process (sent.ts); undefined on a build that
    // lacks `$.state`.
    const proc = { plugin: "starbridge-mod", key: "process" } as const;
    let token: string | undefined;
    try {
      token = (await $.state.get(proc)).value;
      if (!token) {
        token = crypto.randomUUID();
        await $.state.set(proc, token);
      }
    } catch {
      token = undefined;
    }
    const fetch = async (method: string, path: string, body?: unknown) => {
      const headers = body === undefined ? base : { ...base, "content-type": "application/json" };
      const init = { method, ...(body === undefined ? {} : { body: JSON.stringify(body) }) };
      let r: Awaited<ReturnType<typeof $.http.fetch>>;
      if (isPortFile(socket)) {
        // Read each call: the agent writes a new port and token each time it starts.
        const t = portTarget(await $.fs.read(socket));
        const runs =
          t &&
          (await pidRuns(t.pid, env.OS === "Windows_NT", (argv) =>
            $.process.run(argv, { timeoutMs: 10_000 }),
          ));
        if (!t || !runs) throw new Error(`no agent on ${socket}`);
        const signed = await signCall(t.token);
        r = await $.http.fetch(`http://127.0.0.1:${t.port}${path}`, {
          ...init,
          headers: { ...headers, ...signed.headers },
        });
        if (r.headers[PROOF_HEADER] !== signed.expect)
          throw new Error(`no agent on ${socket}: the port answers without its proof`);
      } else
        r = await $.http.fetch(`http://agent${path}`, { ...init, socketPath: socket, headers });
      return { status: r.status, text: r.text };
    };
    const log = (text: string) => $.ui.log(text, { to: "debug" });
    const status = (text: string | undefined) => $.ui.status(text);
    const sessionId = () => $.session.id();
    const now = () => $.clock.now();
    const sleep = (ms: number) => $.clock.sleep(ms);
    const records = new Sent(
      {
        sessionId,
        read: async (path) => ((await $.fs.exists(path)) ? $.fs.read(path) : undefined),
        write: (path, text) => $.fs.write(path, text),
        now,
        submit: (text) => track($.prompt.submit({ text })),
        elsewhere: async (session) => {
          // Claude Code's own pid, as the parent of the shell it runs; Windows has no `sh`.
          if (env.OS === "Windows_NT") return false;
          const own = Number(
            (await $.process.run(["sh", "-c", "echo $PPID"], { timeoutMs: 10_000 })).stdout.trim(),
          );
          if (!own) return false;
          return sessionElsewhere(
            session,
            own,
            { list: (path) => $.fs.list(path), read: (path) => $.fs.read(path) },
            `${env.CLAUDE_CONFIG_DIR || `${env.HOME}/.claude`}/sessions`,
            (pid) => pidRuns(pid, false, (argv) => $.process.run(argv, { timeoutMs: 10_000 })),
          );
        },
        log,
      },
      dir,
      token,
    );
    sent = records;
    /** Whether subagent `agentId` runs now; when unsure, it does. */
    const running = async (agentId: string) => {
      try {
        const status = (await $.agent.list()).find((a) => a.id === agentId)?.status;
        return status === undefined || ["pending", "running", "waiting"].includes(status);
      } catch {
        return true;
      }
    };
    // A subagent's answers go to it, whatever the main agent does (#1702).
    const submit = async (lines: Line[]) => {
      const me = await sessionId();
      const { taken, rest } = await toSubagents(
        lines,
        async (agentId, group, text) => {
          const send = () => $.session.send({ to: { agentId }, text });
          // A subagent that ended is resumed with the message as its prompt, which its transcript
          // keeps; one that runs holds it in memory until its next tool round.
          if (!(await running(agentId))) return send();
          return records.toAgent(
            agentId,
            group.map((l) => forParent(l, agentId)),
            send,
            () => running(agentId),
          );
        },
        log,
        failed,
      );
      // A /clear or /resume during the sends: the rest waits, unconfirmed, for session `me`.
      if (rest.length > 0 && (await sessionId()) !== me) return taken;
      const parent =
        rest.length > 0 ? await handover.submit(rest, (left) => records.send(left)) : [];
      return [...taken, ...parent];
    };
    const starting = () => waiting > 0;
    loop = new Switch(
      {
        // The CLI honours STARBRIDGE_NO_AGENT too, so the CLI path then reaches the server itself.
        agentUp: async () =>
          !env.STARBRIDGE_NO_AGENT && (await fetch("GET", "/v1/status")).status < 300,
        agent: (unconfirmed) =>
          new AgentLoop(
            {
              sessionId,
              cwd: () => $.session.cwd(),
              fetch,
              now,
              sleep,
              submit,
              starting,
              status,
              log,
            },
            unconfirmed,
          ),
        poller: (unconfirmed) =>
          new Poller(
            {
              sessionId,
              run: (argv, timeoutMs) => $.process.run(argv, { timeoutMs }),
              read: (path) => $.fs.read(path),
              write: (path, text) => $.fs.write(path, text),
              mtime: async (path) => (await $.fs.stat(path).catch(() => undefined))?.mtimeMs,
              // The mod's host reads no owner or mode: find does, as plugin/hooks/cli.sh. Windows
              // has no `sh`, and keeps owners in ACLs: there, as `ownedFile`, a file.
              owned: async (path) =>
                env.OS === "Windows_NT"
                  ? (await $.fs.stat(path).catch(() => undefined))?.kind === "file"
                  : (
                      await $.process
                        .run(["sh", "-c", OWNED, "sh", path], { timeoutMs: 10_000 })
                        .catch(() => undefined)
                    )?.exitCode === 0,
              now,
              sleep,
              submit,
              starting,
              status,
              log,
            },
            dir,
            undefined,
            undefined,
            unconfirmed,
          ),
        sleep,
        clearStatus: () => status(undefined),
        log,
      },
      undefined,
      before?.unconfirmed,
    );
    void records.recover().catch((e) => log(`starbridge: ${(e as Error).message}`));
    return started;
  });

  // A subagent's run raises no `turn.start`; its `turn.complete` and tool calls carry its `agentId`.
  on("turn.start", async (_$, e, next) => {
    handover.started();
    await sent?.started(e.text).catch(() => undefined);
    return next(e);
  });

  on("turn.complete", async ($, e, next) => {
    const r = await next(e);
    if (e.agentId !== undefined) {
      const agent = e.agentId;
      const ended = roundEnded.get(agent);
      if (ended !== undefined) void sent?.read(agent, ended).catch(() => undefined);
      // A message that came after its last round waits for another one, which a subagent that
      // finished never runs: the parent gets it instead (#1729).
      void (async () => {
        const list = () => $.agent.list();
        if (!sent || !(await finished(list, (ms) => $.clock.sleep(ms), agent))) return;
        roundEnded.delete(agent);
        if (await sent.finished(agent, ended)) await sent.recover();
      })().catch(() => undefined);
    } else {
      handover.ended();
      // After a `/resume`, or a submit that failed.
      void sent?.recover().catch(() => undefined);
    }
    return r;
  });

  on("tool.call", async ($, e, next) => {
    if (e.agentId !== undefined) {
      const agent = e.agentId;
      // A new round: the subagent read every message sent before its last one ended.
      const ended = roundEnded.get(agent);
      if (ended !== undefined) void sent?.read(agent, ended).catch(() => undefined);
      // The CLI keeps which subagent asked, so its answer goes back there (#1702).
      const command =
        e.tool === "Bash" && typeof e.command === "string" ? tagAsk(e.command, agent) : undefined;
      const r = await next(command !== undefined && command !== e.command ? { ...e, command } : e);
      roundEnded.set(agent, await $.clock.now());
      return r;
    }
    const r = await next(e);
    if (r.deny !== undefined) return r;
    const lines = await handover.take((acks) => loop?.claim(acks) ?? Promise.resolve([]));
    if (lines.length === 0) return r;
    $.ui.log(`starbridge: handed ${lines.length} answer(s) with the ${e.tool} result`, {
      to: "debug",
    });
    return { ...r, context: [...(r.context ?? []), ...lines] };
  });

  // The tag `tool.call` adds is not the subagent's, so the rules judge the command it wrote: where
  // they would ask about the tagged one, the verdict on the untagged one stands (#1702).
  on("tool.check", async ($, e, next) => {
    const verdict = await next(e);
    const input = e.input as { command?: unknown } | undefined;
    if (verdict.decision !== "ask" || verdict.hook !== undefined) return verdict;
    if (e.tool !== "Bash" || typeof input?.command !== "string") return verdict;
    const command = untagAsk(input.command);
    if (command === input.command) return verdict;
    const plain = await $.tool.check({ tool: "Bash", input: { ...input, command } });
    return plain.decision === "ask" ? verdict : plain;
  });

  // After a /clear or a /resume the process goes on under another session id, with no
  // `session.start`, and the loop reads the id each step. Only the end of the process stops it.
  on("session.end", async (_$, e, next) => {
    handover.ended();
    if (e.reason !== "clear" && e.reason !== "resume") {
      await loop?.end();
      loop = undefined;
    }
    return next(e);
  });
};

/** A subagent's statuses once it runs no more rounds. */
const DONE = ["completed", "failed", "killed"];

/**
 * Whether subagent `agentId`, whose turn just completed, runs no more rounds: done, or no longer
 * listed. The engine may mark it a moment after its `turn.complete`, so it looks twice. An idle
 * teammate wakes for a message, so it has not; nor, when the list cannot be read, has any.
 */
export async function finished(
  list: () => Promise<{ id: string; status: string }[]>,
  sleep: (ms: number) => Promise<void>,
  agentId: string,
): Promise<boolean> {
  for (let i = 0; i < 2; i++) {
    if (i > 0) await sleep(2000);
    const agents = await list().catch(() => undefined);
    if (!agents) return false;
    const status = agents.find((a) => a.id === agentId)?.status;
    if (status === undefined || DONE.includes(status)) return true;
  }
  return false;
}

files.hooks/agent.ts:
/**
 * The mod as a thin client of the machine's Starbridge agent (PROTOCOL.md, "Local agent API").
 *
 * Each session long-polls `GET /v1/sessions/<id>/events?wait=25` on the agent's unix socket,
 * submits each event's line into the session and confirms it with `POST /v1/sessions/<id>/ack`.
 * The agent holds the keys and the one connection to the server, so no session runs the CLI,
 * takes a lease or watches files. When no agent answers, `Switch` falls back to `Poller`, the
 * CLI-driven loop, until one does.
 */

import { configDir } from "./poller.ts";

/** The agent API revision this mod speaks, sent in the `starbridge-api` header. */
export const API = 1;
export const VERSION = "0.1.8-rc.4";
const CLIENT = `starbridge-mod/${VERSION}`;

/** Event types this mod submits; others are skipped and left unconfirmed, as the API asks. */
const KNOWN = new Set(["answer"]);

/** An answer's line, and what confirms it. */
export interface Line {
  text: string;
  ack: string;
  /** The Claude Code subagent that asked, which gets the line instead of the session (#1702). */
  subagent?: string;
}

/** Several answers as one message: one line each, in the order they came. */
export const joinLines = (lines: Line[]) => lines.map((l) => l.text).join("\n");

export interface Reply {
  status: number;
  text: string;
}

export interface AgentHost {
  /** The session's id now; a `/clear` changes it. */
  sessionId(): Promise<string>;
  cwd(): Promise<string>;
  /** One HTTP call on the agent's socket. Rejects when it cannot connect or the host aborts it. */
  fetch(method: string, path: string, body?: unknown): Promise<Reply>;
  now(): Promise<number>;
  sleep(ms: number): Promise<void>;
  /**
   * Submits `lines`, every answer one poll brought, as one message (#1597), and returns the acks
   * of those it submitted; a line it could not submit, or holds back for now, stays unconfirmed
   * for a later try. Must not wait for the turn to start: a prompt submitted mid-turn waits for
   * its own.
   */
  submit(lines: Line[]): string[] | Promise<string[]>;
  /**
   * True while a submitted prompt waits for its turn. Claude Code starts a plugin's queued prompt
   * only once the mod's open `fetch` or `run` returns, so the loop then holds no long call (#1446).
   */
  starting(): boolean;
  status(text: string | undefined): void;
  log(text: string): void;
}

export interface AgentTiming {
  /** Seconds the agent may hold one events request (the host aborts a call after 30 s). */
  waitSeconds: number;
  /**
   * An events request that comes back sooner than this with nothing waits out the rest; while a
   * prompt waits for its turn, requests don't wait and this is the time between them.
   */
  minCycleMs: number;
  /** First retry delay after an error, doubled each time up to `maxBackoffMs`. */
  backoffMs: number;
  maxBackoffMs: number;
}

const AGENT_TIMING: AgentTiming = {
  waitSeconds: 25,
  minCycleMs: 2_000,
  backoffMs: 2_000,
  maxBackoffMs: 60_000,
};

const hex = (bytes: Uint8Array) => [...bytes].map((b) => b.toString(16).padStart(2, "0")).join("");

/**
 * The CLI's `configKey` (cli/src/agent/api.ts) of config folder `dir`: the first 16 hex digits of
 * the SHA-256 of its path, with runs of `/` as one, no trailing `/`, and on Windows `\` as `/`.
 * Sent as `CONFIG_HEADER`, so an agent of another config folder refuses the call (#1966).
 */
export async function configKey(dir: string, windows = false): Promise<string> {
  const path = (windows ? dir.replace(/\\/g, "/") : dir)
    .replace(/\/+/g, "/")
    .replace(/(.)\/$/, "$1");
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(path));
  return hex(new Uint8Array(digest)).slice(0, 16);
}

export const CONFIG_HEADER = "starbridge-config";

/**
 * Where the agent listens, as the CLI's `socketPath` (cli/src/agent/api.ts) works it out:
 * `$STARBRIDGE_AGENT_SOCKET`; on Windows (`OS=Windows_NT`) the port file `agent.port` in the
 * config directory; for the default config directory
 * `$XDG_RUNTIME_DIR/starbridge/agent-<configKey>.sock` when that is set; else `agent.sock` in the
 * config directory. `config` is the key to send, undefined when `$STARBRIDGE_AGENT_SOCKET` names
 * the agent.
 */
export async function agentAddress(env: {
  STARBRIDGE_AGENT_SOCKET?: string;
  STARBRIDGE_CONFIG_DIR?: string;
  XDG_CONFIG_HOME?: string;
  XDG_RUNTIME_DIR?: string;
  HOME?: string;
  USERPROFILE?: string;
  OS?: string;
}): Promise<{ socket: string; config?: string }> {
  const dir = configDir(env);
  if (env.STARBRIDGE_AGENT_SOCKET) return { socket: env.STARBRIDGE_AGENT_SOCKET };
  const config = await configKey(dir, env.OS === "Windows_NT");
  if (env.OS === "Windows_NT") return { socket: `${dir}/agent.port`, config };
  const standard = configDir({ ...env, STARBRIDGE_CONFIG_DIR: undefined });
  if (env.XDG_RUNTIME_DIR && dir === standard)
    return { socket: `${env.XDG_RUNTIME_DIR}/starbridge/agent-${config}.sock`, config };
  return { socket: `${dir}/agent.sock`, config };
}

/**
 * An address ending in `.port` names the file where an agent on loopback TCP wrote its port and
 * its token, which calls prove they hold without sending it (the CLI's `PortFile` and `proof`).
 */
export const isPortFile = (address: string) => address.endsWith(".port");

/**
 * The port, the token and the agent's pid in port file `text`; undefined when it is not one, as
 * the CLI's `readPortFile` reads it.
 */
export function portTarget(text: string): { port: number; token: string; pid: number } | undefined {
  try {
    const f = JSON.parse(text) as { port?: unknown; token?: unknown; pid?: unknown };
    if (
      Number.isInteger(f.port) &&
      typeof f.token === "string" &&
      f.token.length >= 32 &&
      Number.isInteger(f.pid)
    )
      return { port: f.port as number, token: f.token, pid: f.pid as number };
  } catch {}
  return undefined;
}

/**
 * Whether process `pid` runs, for a host that can run commands but not signal a process:
 * `tasklist` on Windows, `ps` elsewhere. A call sends nothing to a port whose agent's pid runs no
 * more, as the CLI does (#570): a dead agent's port shows in `netstat` to every local user, and
 * whoever takes it would get the call's body before failing its proof. A check that cannot run
 * counts as not running, so the mod falls back to the CLI.
 */
export async function pidRuns(
  pid: number,
  windows: boolean,
  run: (argv: string[]) => Promise<{ exitCode: number | null; stdout: string }>,
): Promise<boolean> {
  try {
    if (windows) {
      // One CSV row per match, `"image","pid",…`; with none, a message in the system's language.
      const r = await run(["tasklist", "/FI", `PID eq ${pid}`, "/FO", "CSV", "/NH"]);
      return r.exitCode === 0 && new RegExp(`^"[^"]*","${pid}",`, "m").test(r.stdout);
    }
    const r = await run(["ps", "-p", String(pid), "-o", "pid="]);
    return r.exitCode === 0 && r.stdout.trim() === String(pid);
  } catch {
    return false;
  }
}

async function proof(token: string, role: "client" | "agent", nonce: string): Promise<string> {
  const data = new TextEncoder().encode(`${token}:${role}:${nonce}`);
  return hex(new Uint8Array(await crypto.subtle.digest("SHA-256", data)));
}

/**
 * The headers that prove a call holds `token`, and the `starbridge-proof` header the agent's
 * answer must carry: anything that answers without it took the port of an agent that stopped.
 */
export async function signCall(token: string): Promise<{
  headers: Record<string, string>;
  expect: string;
}> {
  const nonce = hex(crypto.getRandomValues(new Uint8Array(16)));
  return {
    headers: {
      "starbridge-nonce": nonce,
      authorization: `Starbridge ${await proof(token, "client", nonce)}`,
    },
    expect: await proof(token, "agent", nonce),
  };
}

export const PROOF_HEADER = "starbridge-proof";

/** The headers every call carries. */
export const HEADERS: Record<string, string> = {
  "starbridge-api": String(API),
  "user-agent": CLIENT,
};

interface Event {
  type?: unknown;
  ack?: unknown;
  line?: unknown;
  decisionId?: unknown;
  subagent?: unknown;
}

/** Why `AgentLoop.run` returned: `stop`, or the agent cannot serve this mod. */
export type Ended = "stopped" | "unreachable";

export class AgentLoop {
  private stopped = false;
  private failures = 0;
  /** The session id `hello` last went out under. */
  private greeted: string | undefined;

  constructor(
    private readonly host: AgentHost,
    /** Lines submitted but not yet confirmed, shared with `Poller` so a switch submits nothing twice. */
    private readonly unconfirmed: Set<string>,
    private readonly t: AgentTiming = AGENT_TIMING,
  ) {}

  /** Ends the loop after the current step. */
  stop() {
    this.stopped = true;
  }

  /** Runs until `stop`, or until a call cannot reach the agent or gets a 426. */
  async run(): Promise<Ended> {
    while (!this.stopped) {
      try {
        await this.step();
      } catch (e) {
        // A call that never connected, one the host aborted (the agent is gone or hung), or a
        // 426 (it speaks another API revision).
        this.host.log(`starbridge: agent unreachable: ${(e as Error).message}`);
        return "unreachable";
      }
    }
    return "stopped";
  }

  /**
   * Confirms the events among `acks` that the agent still hands this session, and returns those:
   * a line a `wait` or `waiting` printed meanwhile is not handed over again (#1484).
   */
  async claim(acks: string[]): Promise<string[]> {
    const me = await this.host.sessionId();
    const r = await this.host.fetch("GET", `${path(me)}/events?wait=0`);
    if (r.status < 200 || r.status >= 300) return [];
    const pending = new Set((parse<{ events?: Event[] }>(r.text)?.events ?? []).map((e) => e.ack));
    const mine = acks.filter((a) => pending.has(a));
    if (mine.length === 0) return [];
    const ack = await this.host.fetch("POST", `${path(me)}/ack`, { acks: mine });
    if (ack.status < 200 || ack.status >= 300) return [];
    // What it confirmed now: not a line a `wait` or `waiting` took since the read. An agent older
    // than that names none.
    return parse<{ acked?: string[] }>(ack.text)?.acked ?? mine;
  }

  /** Tells the agent the session ended, so its session-scoped state goes. */
  async bye(): Promise<void> {
    const me = this.greeted;
    if (!me) return;
    await this.host.fetch("POST", `${path(me)}/bye`).catch(() => undefined);
  }

  private async step() {
    const me = await this.host.sessionId();
    if (!me) {
      await this.host.sleep(this.t.minCycleMs);
      return;
    }
    if (this.greeted !== me) {
      // After a /clear: the old id has no mod any more (#537).
      const replaces = this.greeted ? { replaces: this.greeted } : {};
      const r = await this.host.fetch("POST", `${path(me)}/hello`, {
        cwd: await this.host.cwd(),
        ...replaces,
      });
      if (!(await this.ok(r))) return;
      this.greeted = me;
    }
    const started = await this.host.now();
    const wait = this.host.starting() ? 0 : this.t.waitSeconds;
    const r = await this.host.fetch("GET", `${path(me)}/events?wait=${wait}`);
    if (!(await this.ok(r))) return;
    const events = (parse<{ events?: Event[] }>(r.text)?.events ?? []).filter(
      (e): e is Event & { ack: string; line: string } =>
        typeof e.type === "string" &&
        KNOWN.has(e.type) &&
        typeof e.ack === "string" &&
        typeof e.line === "string",
    );
    // A /clear during the call made another session current: the events wait, unconfirmed,
    // until session `me` is resumed.
    if (events.length > 0 && (await this.host.sessionId()) !== me) {
      this.host.log(
        `starbridge: held back the answers ${events.map((l) => l.ack).join(", ")}: their session ${me} ended`,
      );
      return;
    }
    const due = events.filter((e) => !this.unconfirmed.has(e.ack));
    const taken =
      due.length > 0
        ? await this.host.submit(
            due.map((e) => ({
              text: e.line,
              ack: e.ack,
              ...(typeof e.subagent === "string" ? { subagent: e.subagent } : {}),
            })),
          )
        : [];
    for (const a of taken) this.unconfirmed.add(a);
    const handed = taken.length;
    const done = events.filter((e) => this.unconfirmed.has(e.ack)).map((e) => e.ack);
    if (done.length > 0) {
      const ack = await this.host.fetch("POST", `${path(me)}/ack`, { acks: done });
      if (!(await this.ok(ack))) return;
      for (const a of done) this.unconfirmed.delete(a);
    }
    const left = started + this.t.minCycleMs - (await this.host.now());
    if (handed === 0 && left > 0) await this.host.sleep(left);
  }

  /** True on a 2xx; otherwise shows the agent's reason and waits before the next try. */
  private async ok(r: Reply): Promise<boolean> {
    if (r.status >= 200 && r.status < 300) {
      if (this.failures > 0) this.host.status(undefined);
      this.failures = 0;
      return true;
    }
    const body = parse<{ error?: string; detail?: string }>(r.text);
    const reason = body?.detail ?? body?.error ?? `status ${r.status}`;
    // 426: the agent and this mod cannot work together; 421: it serves another config folder
    // (#1966). The CLI's own path still can.
    if (r.status === 426 || r.status === 421) throw new Error(reason);
    this.failures++;
    const delay = Math.min(this.t.maxBackoffMs, this.t.backoffMs * 2 ** (this.failures - 1));
    const text = `starbridge: ${reason}`;
    this.host.status(text);
    this.host.log(`${text}; retrying in ${Math.round(delay / 1000)} s`);
    await this.host.sleep(delay);
    return false;
  }
}

function path(session: string): string {
  return `/v1/sessions/${encodeURIComponent(session)}`;
}

function parse<T>(text: string): T | undefined {
  try {
    return JSON.parse(text) as T;
  } catch {
    return undefined;
  }
}

