import type { Line } from "./agent.ts";

/**
 * The answer loop, apart from the engine's `$` so plain tests can drive it.
 *
 * Every session that loads the mod runs this loop, but only one per machine polls the server: the
 * holder of a lease file in the CLI's config directory. The holder runs `starbridge answers
 * --session <its id> --wait 25` back to back (the host aborts a call after 30 s); the others
 * watch the CLI's state file and run `starbridge answers --session <id>` without `--wait` when
 * it changes, which never touches the network. The CLI holds the keys, opens and verifies each
 * answer, and hands a session only the answers to decisions it asked, until the poller confirms
 * it submitted them with `starbridge answers --ack`.
 */

export interface Host {
  /** The session's id now; a `/clear` changes it. */
  sessionId(): Promise<string>;
  run(
    argv: string[],
    timeoutMs: number,
  ): Promise<{ exitCode: number | null; stdout: string; stderr: string }>;
  /** Rejects when the file is missing. */
  read(path: string): Promise<string>;
  write(path: string, text: string): Promise<void>;
  /** Undefined when the file is missing. */
  mtime(path: string): Promise<number | undefined>;
  /**
   * Whether `path` is a file owned by this user or root that no one else may write (`ownedFile`,
   * node.ts), so another user cannot pick the CLI that starts.
   */
  owned(path: string): Promise<boolean>;
  now(): Promise<number>;
  sleep(ms: number): Promise<void>;
  /** `AgentHost.submit`: one message for the lines one read brought, returning the acks it took. */
  submit(lines: Line[]): string[] | Promise<string[]>;
  /** True while a submitted prompt waits for its turn: `AgentHost.starting`. */
  starting(): boolean;
  status(text: string | undefined): void;
  log(text: string): void;
}

export interface Timing {
  /** Seconds the server may hold one poll. */
  waitSeconds: number;
  /** How often a session that does not poll checks the state file. */
  checkMs: number;
  /** How often it reads its answers even when no change of the state file was seen. */
  recheckMs: number;
  /** How long a lease lasts past its last renewal. */
  leaseMs: number;
  /**
   * A poll that comes back sooner than this with nothing waits out the rest; while a prompt waits
   * for its turn, polls don't wait and this is the time between them.
   */
  minCycleMs: number;
  /** First retry delay after an error, doubled each time up to `maxBackoffMs`. */
  backoffMs: number;
  maxBackoffMs: number;
}

const TIMING: Timing = {
  waitSeconds: 25,
  checkMs: 2_000,
  recheckMs: 30_000,
  leaseMs: 60_000,
  minCycleMs: 2_000,
  backoffMs: 2_000,
  maxBackoffMs: 60_000,
};

interface Lease {
  session: string;
  until: number;
}

/**
 * `$STARBRIDGE_CONFIG_DIR`, else `$XDG_CONFIG_HOME/starbridge`, else `~/.config/starbridge`, as
 * the CLI; on Windows (`OS=Windows_NT`) home is `USERPROFILE`, as the CLI reads it, whatever
 * `HOME` a Git Bash set.
 */
/** Whether `path` is absolute, on Windows too: a relative one would depend on the agent's folder. */
export const absolute = (path: string) => /^(\/|[A-Za-z]:[\\/])/.test(path);

export function configDir(env: {
  STARBRIDGE_CONFIG_DIR?: string;
  XDG_CONFIG_HOME?: string;
  HOME?: string;
  USERPROFILE?: string;
  OS?: string;
}): string {
  if (env.STARBRIDGE_CONFIG_DIR) return env.STARBRIDGE_CONFIG_DIR;
  const home = env.OS === "Windows_NT" ? env.USERPROFILE || env.HOME : env.HOME || env.USERPROFILE;
  return `${env.XDG_CONFIG_HOME || `${home}/.config`}/starbridge`;
}

/** The CLI's first error line, without the "starbridge: " the status line adds again. */
function firstLine(stderr: string): string {
  return (stderr.trim().split("\n")[0] ?? "").replace(/^starbridge:\s*/, "");
}

export class Poller {
  private stopped = false;
  private failures = 0;
  /** Lines the host held back in the last `answers`. */
  private held = 0;
  /** The state file's time when this session last read it; a /clear makes it unread again. */
  private seen: { session: string; mtime: number; at: number } | undefined;
  /** The session id this poller last held the lease under; a `/clear` changes the id. */
  private leasedAs: string | undefined;
  private readonly leasePath: string;
  private readonly cliPath: string;
  private readonly statePath: string;
  /** Resolves when the loop has ended. */
  readonly done: Promise<void>;

  constructor(
    private readonly host: Host,
    dir: string,
    /** The CLI; by default the path setup recorded in `dir`, else `starbridge` on the PATH (#612). */
    private readonly command?: string,
    private readonly t: Timing = TIMING,
    /**
     * Lines submitted but not yet confirmed, so a retried confirm submits nothing twice; shared
     * with `AgentLoop` (agent.ts) across a switch.
     */
    private readonly unconfirmed = new Set<string>(),
  ) {
    this.leasePath = `${dir}/mod-poller.json`;
    this.cliPath = `${dir}/cli-path`;
    this.statePath = `${dir}/state.json`;
    // Nothing awaits a loop that ended before `stop`: a rejection would take the harness down (#1365).
    this.done = this.loop().catch((e) => {
      try {
        this.host.log(`starbridge: the answer loop stopped: ${(e as Error).message}`);
      } catch {}
    });
  }

  /**
   * Ends the loop after the current step and gives up the lease at once, so another session polls.
   * Never rejects: it runs after the session ended, when the host may throw (#1365).
   */
  async stop(): Promise<void> {
    this.stopped = true;
    try {
      const me = await this.host.sessionId();
      const lease = await this.readLease();
      if (lease && (lease.session === me || lease.session === this.leasedAs))
        await this.host.write(this.leasePath, JSON.stringify({ ...lease, until: 0 }));
    } catch {
      // The lease runs out on its own.
    }
  }

  private async cli(): Promise<string> {
    if (this.command) return this.command;
    try {
      if (!(await this.host.owned(this.cliPath))) return "starbridge";
      const recorded = (await this.host.read(this.cliPath)).trim();
      // A binary removed since setup recorded it: the PATH may still hold another.
      if (absolute(recorded) && (await this.host.owned(recorded))) return recorded;
    } catch {}
    return "starbridge";
  }

  private async loop() {
    while (!this.stopped) {
      try {
        await this.step();
      } catch (e) {
        await this.fail((e as Error).message);
      }
    }
  }

  private async step() {
    const me = await this.host.sessionId();
    if (!me) {
      await this.host.sleep(this.t.checkMs);
      return;
    }
    if (await this.lease(me, this.t.leaseMs)) {
      const started = await this.host.now();
      const wait = this.host.starting() ? 0 : this.t.waitSeconds;
      const handed = await this.answers(me, ["--wait", String(wait)]);
      if (handed === undefined) return;
      const left = started + this.t.minCycleMs - (await this.host.now());
      if (handed === 0 && left > 0) await this.host.sleep(left);
      return;
    }
    const mtime = await this.host.mtime(this.statePath);
    const now = await this.host.now();
    const unchanged = this.seen?.session === me && this.seen.mtime === mtime;
    if (mtime === undefined || (unchanged && now - (this.seen?.at ?? 0) < this.t.recheckMs)) {
      await this.host.sleep(this.t.checkMs);
      return;
    }
    if ((await this.answers(me, [])) === undefined) return;
    // A line the host held back for the turn's end is read again at the next check (#1484).
    if (this.held === 0) this.seen = { session: me, mtime, at: now };
    else await this.host.sleep(this.t.checkMs);
  }

  /**
   * Confirms the lines among `acks` that the CLI still hands this session, and returns those: a
   * line a `wait` or `waiting` printed meanwhile is not handed over again (#1484).
   */
  async claim(acks: string[]): Promise<string[]> {
    const me = await this.host.sessionId();
    const base = [await this.cli(), "answers", "--session", me];
    const timeoutMs = (this.t.waitSeconds + 30) * 1000;
    const r = await this.host.run(base, timeoutMs);
    if (r.exitCode !== 0) return [];
    const pending = new Set<string>();
    for (const text of r.stdout.split("\n")) {
      try {
        const l = JSON.parse(text) as { decisionId?: unknown; ack?: unknown };
        const ack = typeof l.ack === "string" ? l.ack : l.decisionId;
        if (typeof ack === "string") pending.add(ack);
      } catch {}
    }
    const mine = acks.filter((a) => pending.has(a));
    if (mine.length === 0) return [];
    const ack = await this.host.run([...base, ...mine.flatMap((a) => ["--ack", a])], timeoutMs);
    if (ack.exitCode !== 0) return [];
    // What it confirmed now: not a line a `wait` or `waiting` took since the read. A CLI older
    // than that prints nothing.
    try {
      const acked = (JSON.parse(ack.stdout) as { acked?: unknown }).acked;
      if (Array.isArray(acked)) return acked.filter((a): a is string => typeof a === "string");
    } catch {}
    return mine;
  }

  /**
   * Runs one `starbridge answers`, submits each answer it hands over and confirms them. Returns
   * how many, or undefined after an error, which it has already waited out.
   */
  private async answers(me: string, extra: string[]): Promise<number | undefined> {
    const timeoutMs = (this.t.waitSeconds + 30) * 1000;
    const base = [await this.cli(), "answers", "--session", me];
    const r = await this.host.run([...base, ...extra], timeoutMs);
    if (r.exitCode !== 0) {
      await this.fail(firstLine(r.stderr) || `exit ${r.exitCode}`);
      return undefined;
    }
    // Warnings on success, such as an answer that failed its checks.
    for (const line of r.stderr.split("\n")) if (line.trim()) this.host.log(line);
    if (this.failures > 0) this.host.status(undefined);
    this.failures = 0;
    const lines: Line[] = [];
    for (const text of r.stdout.split("\n")) {
      if (!text.trim()) continue;
      let parsed: { decisionId?: unknown; ack?: unknown; line?: unknown; subagent?: unknown };
      try {
        parsed = JSON.parse(text);
      } catch {
        this.host.log(`starbridge: unreadable line from the CLI: ${text.slice(0, 200)}`);
        continue;
      }
      const { decisionId: id, line } = parsed;
      if (typeof id !== "string" || typeof line !== "string") continue;
      lines.push({
        text: line,
        ack: typeof parsed.ack === "string" ? parsed.ack : id,
        ...(typeof parsed.subagent === "string" ? { subagent: parsed.subagent } : {}),
      });
    }
    // A /clear during the call made another session current: the answers wait, unconfirmed,
    // until session `me` is resumed.
    if (lines.length > 0 && (await this.host.sessionId()) !== me) {
      this.host.log(
        `starbridge: held back the answers ${lines.map((l) => l.ack).join(", ")}: their session ${me} ended`,
      );
      this.held = 0;
      return 0;
    }
    const due = lines.filter((l) => !this.unconfirmed.has(l.ack));
    const taken = due.length > 0 ? await this.host.submit(due) : [];
    for (const a of taken) this.unconfirmed.add(a);
    const handed = taken.length;
    const held = due.length - handed;
    const done = lines.filter((l) => this.unconfirmed.has(l.ack)).map((l) => l.ack);
    if (done.length > 0) {
      const ack = await this.host.run([...base, ...done.flatMap((id) => ["--ack", id])], timeoutMs);
      if (ack.exitCode !== 0) {
        await this.fail(firstLine(ack.stderr) || `exit ${ack.exitCode}`);
        return undefined;
      }
      for (const id of done) this.unconfirmed.delete(id);
    }
    this.held = held;
    return handed;
  }

  /** Waits before the next try, twice as long after each error in a row. */
  private async fail(message: string) {
    this.failures++;
    const delay = Math.min(this.t.maxBackoffMs, this.t.backoffMs * 2 ** (this.failures - 1));
    const text = `starbridge: ${message}`;
    this.host.status(text);
    this.host.log(`${text}; retrying in ${Math.round(delay / 1000)} s`);
    // A poller that backs off keeps its lease, so the other sessions do not all start failing.
    try {
      const me = await this.host.sessionId();
      const held = (await this.readLease())?.session;
      if (me && held !== undefined && (held === me || held === this.leasedAs))
        await this.lease(me, delay + this.t.leaseMs);
    } catch {
      // The lease is an optimisation; losing it costs one more poller.
    }
    await this.host.sleep(delay);
  }

  private async readLease(): Promise<Lease | undefined> {
    try {
      const lease = JSON.parse(await this.host.read(this.leasePath)) as Lease;
      return typeof lease.session === "string" && typeof lease.until === "number"
        ? lease
        : undefined;
    } catch {
      return undefined;
    }
  }

  /**
   * Takes or renews the lease unless another live session holds it. Two sessions that write at
   * once both read back the last write, so at most one goes on to poll; a double poll would
   * still be harmless, since the CLI keeps each answer once and hands it over once.
   */
  private async lease(me: string, forMs: number): Promise<boolean> {
    // A step still running when `stop` gave the lease up must not take it back.
    if (this.stopped) return false;
    const now = await this.host.now();
    const held = await this.readLease();
    const ours = held?.session === me || (held !== undefined && held.session === this.leasedAs);
    if (held && !ours && held.until > now) return false;
    const mine = ours && (held?.until ?? 0) > now;
    await this.host.write(this.leasePath, JSON.stringify({ session: me, until: now + forMs }));
    if (!mine) {
      await this.host.sleep(100);
      if ((await this.readLease())?.session !== me) return false;
    }
    this.leasedAs = me;
    return true;
  }
}

files.hooks/sent.ts:
/**
 * Answers the mod submitted as prompts, kept until their turn starts (#1517).
 *
 * The loops confirm a line to the CLI or the agent as soon as they submit it, so a `wait` or
 * `waiting` never prints an answer already queued as a prompt. But Claude Code keeps a queued
 * prompt in memory only: one still waiting for its turn when the process exits is gone, and
 * `--resume` does not bring it back. So each line is written to a file of its session before it
 * is submitted, and leaves it once its turn starts: `turn.start` carries its text, or
 * `$.prompt.submit` resolves. A process that starts on a session whose file still holds lines
 * from another process submits them again.
 *
 * Lines carry the token of the process that submitted them, which `$.state` keeps across a hot
 * reload: a reload leaves the queued prompt in place, so a reloaded mod submits nothing again.
 * Nor does a process that shares its session with another live one.
 *
 * Every operation reads the file afresh, since another process on the session writes it too.
 */

export interface SentHost {
  /** The session's id now; a `/clear` or a `/resume` changes it. */
  sessionId(): Promise<string>;
  /** Undefined when the file is missing; rejects when it cannot be read. */
  read(path: string): Promise<string | undefined>;
  /** Creates the file's folder as needed. */
  write(path: string, text: string): Promise<void>;
  now(): Promise<number>;
  /**
   * `$.prompt.submit`: resolves when the prompt's turn starts, or to `{ drop }` when a hook
   * refused it.
   */
  submit(text: string): Promise<unknown>;
  /**
   * Whether another live process runs `session`, such as a `claude --resume` in a second
   * terminal: the lines it submitted may still be queued there.
   */
  elsewhere(session: string): Promise<boolean>;
  log(text: string): void;
}

interface Line {
  ack: string;
  line: string;
  /** The token of the process that submitted it last; empty when that submit failed. */
  process: string;
  at: number;
  /** Submits a hook refused or the engine rejected; a process exiting is not one. */
  refused: number;
  /**
   * Sent to this subagent, which has not read it yet (#1702); `line` is then what the parent gets
   * if the process exits first.
   */
  agent?: string;
}

/** Refused submits after which a line is dropped, with a log line. */
const MAX_REFUSED = 3;
/** A line older than this is dropped: the server drops an unanswered decision after 30 days. */
const MAX_AGE_MS = 30 * 24 * 3600_000;

export class Sent {
  /** Sessions whose file this process read. */
  private readonly sessions = new Set<string>();
  /** Sessions whose lines from other processes went out again. */
  private readonly recovered = new Set<string>();
  /** Every operation runs alone, from its read to its submit. */
  private queue: Promise<unknown> = Promise.resolve();

  constructor(
    private readonly host: SentHost,
    private readonly dir: string,
    /**
     * This process's token; undefined where `$.state` is missing, and then no line is submitted
     * again, since a reload could not be told from a new process.
     */
    private readonly process: string | undefined,
  ) {}

  /**
   * Records `batch`, then submits it as one prompt (#1597). Returns the acks of the lines that went
   * out, now or before: not those it could not record, or that a `/clear` or `/resume` held back
   * meanwhile, which the loop leaves unconfirmed for a later try.
   */
  send(batch: { text: string; ack: string }[]): Promise<string[]> {
    return this.alone(async () => {
      const me = await this.host.sessionId();
      const at = await this.host.now();
      let lines = await this.loaded(me);
      if (!lines) return [];
      const entries: Line[] = [];
      /** Lines already out, from this process or another. */
      const out: string[] = [];
      for (const { text, ack } of batch) {
        // A process that died between recording a line and confirming it leaves both: the loop
        // hands the line over again, and the file holds it. It goes out once, as `recover` would.
        let known: Line | undefined = lines.find((l) => l.ack === ack);
        if (known && (this.process === undefined || known.process === this.process)) {
          out.push(ack);
          continue;
        }
        if (known && known.process !== "") {
          if (await this.host.elsewhere(me).catch(() => false)) {
            out.push(ack);
            continue;
          }
          // The process may have run the line's turn before it exited: then the file lacks it. A
          // process that started meanwhile may hold it now.
          const before = known.process;
          const fresh = await this.loaded(me);
          if (!fresh) return out;
          lines = [...fresh.filter((l) => !entries.some((e) => e.ack === l.ack)), ...entries];
          known = lines.find((l) => l.ack === ack);
          if (!known || (known.process !== "" && known.process !== before)) {
            out.push(ack);
            continue;
          }
        }
        const entry: Line = known
          ? { ...known, process: this.process ?? "" }
          : { ack, line: text, process: this.process ?? "", at, refused: 0 };
        lines = [...lines.filter((l) => l !== known), entry];
        entries.push(entry);
      }
      if (entries.length === 0) return out;
      try {
        await this.save(me, lines);
      } catch (e) {
        const acks = entries.map((l) => l.ack).join(", ");
        this.host.log(`starbridge: could not record the answers ${acks}: ${(e as Error).message}`);
        return out;
      }
      if ((await this.host.sessionId()) !== me) {
        // Left for session `me`: the loop holds the lines back until it is current again.
        const left = lines.map((l) => (entries.includes(l) ? { ...l, process: "" } : l));
        await this.save(me, left).catch(() => undefined);
        return out;
      }
      this.enter(me, entries);
      return [...out, ...entries.map((l) => l.ack)];
    });
  }

  /**
   * Records `batch` for subagent `agent`, as the prompt the parent gets should the process exit
   * before the subagent reads it (#1702), then runs `deliver`, the send. A send that fails leaves
   * no record. Claude Code keeps a message for a running subagent in memory until its next tool
   * round, so `read` drops the record only once the subagent has moved on. `running` is asked
   * again once the record is saved, right before the send: a subagent that finished meanwhile is
   * resumed with the message, which needs no record, and `finished` must not hand it to the parent
   * too (#1729).
   */
  toAgent(
    agent: string,
    batch: { text: string; ack: string }[],
    deliver: () => Promise<{ isDelivered: boolean; reason?: string }>,
    running: () => Promise<boolean> = async () => true,
  ): Promise<{ isDelivered: boolean; reason?: string }> {
    // Without a token a reload could not be told from a new process: nothing to recover by.
    if (this.process === undefined) return deliver();
    const process = this.process;
    return this.alone(async () => {
      const me = await this.host.sessionId();
      const at = await this.host.now();
      const acks = batch.map((l) => l.ack);
      const lines = await this.loaded(me);
      const entries = batch.map((l) => ({
        ack: l.ack,
        line: l.text,
        process,
        at,
        refused: 0,
        agent,
      }));
      const rest = lines?.filter((l) => !acks.includes(l.ack));
      const saved =
        rest !== undefined &&
        (await this.save(me, [...rest, ...entries]).then(
          () => true,
          (e) => {
            this.host.log(
              `starbridge: could not record the answers ${acks.join(", ")}: ${(e as Error).message}`,
            );
            return false;
          },
        ));
      // Sent without a record, an answer the subagent never read would be lost with the process.
      if (!saved) return { isDelivered: false, reason: "could not record it" };
      if (!(await running())) {
        await this.save(me, rest).catch(() => undefined);
        return deliver();
      }
      let r: { isDelivered: boolean; reason?: string };
      try {
        r = await deliver();
      } catch (e) {
        await this.save(me, rest).catch(() => undefined);
        throw e;
      }
      if (!r.isDelivered) await this.save(me, rest).catch(() => undefined);
      return r;
    });
  }

  /**
   * Subagent `agent` read what was sent to it up to `before`, the end of a tool round of its own:
   * Claude Code hands a subagent its messages after each round. Those records go.
   */
  read(agent: string, before: number): Promise<void> {
    return this.alone(async () => {
      // After a hot reload the current session is the one its records are under.
      await this.load(await this.host.sessionId()).catch(() => undefined);
      for (const session of this.sessions) {
        const lines = await this.load(session).catch(() => undefined);
        if (!lines) continue;
        const keep = lines.filter((l) => l.agent !== agent || l.at > before);
        if (keep.length < lines.length) await this.save(session, keep).catch(() => undefined);
      }
    });
  }

  /**
   * Subagent `agent` finished, its last tool round ending at `before` (undefined when this module
   * saw none): what was sent to it after then, it never read (#1729). Those records become lines
   * for the parent, which the next `recover` submits; the rest go. Returns whether any are left
   * for the parent.
   */
  finished(agent: string, before: number | undefined): Promise<boolean> {
    return this.alone(async () => {
      await this.load(await this.host.sessionId()).catch(() => undefined);
      let left = false;
      for (const session of this.sessions) {
        const lines = await this.load(session).catch(() => undefined);
        if (!lines?.some((l) => l.agent === agent)) continue;
        const keep: Line[] = [];
        for (const l of lines) {
          if (l.agent !== agent) keep.push(l);
          else if (before === undefined || l.at > before) {
            const { agent: _, ...line } = l;
            keep.push({ ...line, process: "" });
            left = true;
          }
        }
        await this.save(session, keep).catch(() => undefined);
      }
      return left;
    });
  }

  /**
   * A turn started with `text`: each line it carries reached the model. Checks every session read
   * so far, since a `/clear` may come between the submit and the turn.
   */
  started(text: string): Promise<void> {
    return this.alone(async () => {
      await this.load(await this.host.sessionId());
      for (const session of this.sessions) {
        const lines = await this.load(session);
        const left = lines.filter((l) => !text.includes(l.line));
        if (left.length < lines.length) await this.save(session, left).catch(() => undefined);
      }
    });
  }

  /**
   * Submits again the current session's lines that another process submitted, or whose submit
   * failed, once per session id, and not while another live process runs the session. Then these come from this process, and only a turn start or a
   * failed submit changes them.
   */
  recover(): Promise<void> {
    return this.alone(async () => {
      if (this.process === undefined) return;
      const me = await this.host.sessionId();
      if (!me) return;
      let lines = await this.load(me);
      // Other processes' lines go out once another live process no longer runs this session:
      // checked again at each turn's end until then.
      const theirs = (l: Line) => l.process !== "" && l.process !== this.process;
      const key = (l: Line) => `${l.ack}\n${l.process}`;
      const found = new Set(lines.filter(theirs).map(key));
      let take = false;
      if (!this.recovered.has(me)) {
        take = !(found.size > 0 && (await this.host.elsewhere(me).catch(() => false)));
        // A process that exited may have run some of its lines' turns since the first read, and
        // one that started meanwhile may have recorded its own, which stay with it.
        if (take && found.size > 0) lines = await this.load(me);
      }
      const due = lines.filter((l) => l.process === "" || (take && found.has(key(l))));
      if (due.length === 0) {
        if (take) this.recovered.add(me);
        return;
      }
      const keep = lines.filter((l) => !due.includes(l));
      const again: Line[] = [];
      for (const l of due)
        if (l.refused >= MAX_REFUSED)
          this.host.log(`starbridge: gave up on the answer ${l.ack}: refused ${l.refused} times`);
        else again.push({ ...l, process: this.process });
      // Marked once saved: a failed write leaves the lines to the next try.
      await this.save(me, [...keep, ...again]);
      if (take) this.recovered.add(me);
      if ((await this.host.sessionId()) !== me) {
        // Left for session `me`, as `send` leaves a line.
        this.recovered.delete(me);
        const free = again.map((l) => ({ ...l, process: "" }));
        await this.save(me, [...keep, ...free]).catch(() => undefined);
        return;
      }
      for (const l of again)
        this.host.log(`starbridge: submitting the answer ${l.ack} again: its prompt never ran`);
      if (again.length > 0) this.enter(me, again);
    });
  }

  /** Submits `entries` as one prompt, one line each. */
  private enter(session: string, entries: Line[]) {
    const acks = entries.map((l) => l.ack);
    this.host.submit(entries.map((l) => l.line).join("\n")).then(
      (r) => {
        const drop = (r as { drop?: unknown } | undefined)?.drop;
        if (typeof drop === "string") void this.failed(session, acks, `refused: ${drop}`);
        else void this.done(session, acks);
      },
      (e) => void this.failed(session, acks, (e as Error)?.message ?? String(e)),
    );
  }

  /** `$.prompt.submit` resolved: the lines' turn started. */
  private done(session: string, acks: string[]) {
    return this.alone(async () => {
      const lines = await this.load(session);
      if (lines.some((l) => acks.includes(l.ack)))
        await this.save(
          session,
          lines.filter((l) => !acks.includes(l.ack)),
        ).catch(() => undefined);
    });
  }

  /** The submit failed: the next `recover` submits the lines again. */
  private failed(session: string, acks: string[], why: string) {
    this.host.log(`starbridge: the answers ${acks.join(", ")} did not go in: ${why}`);
    return this.alone(async () => {
      const lines = await this.load(session);
      if (!lines.some((l) => acks.includes(l.ack))) return;
      await this.save(
        session,
        lines.map((l) =>
          acks.includes(l.ack) ? { ...l, process: "", refused: l.refused + 1 } : l,
        ),
      ).catch(() => undefined);
    });
  }

  private alone<T>(op: () => Promise<T>): Promise<T> {
    const run = this.queue.then(op);
    this.queue = run.catch(() => undefined);
    return run;
  }

  private path(session: string) {
    return `${this.dir}/mod-sent/${encodeURIComponent(session)}.json`;
  }

  /**
   * Rejects when the file cannot be read, so that no write replaces lines it could not see. One
   * that does not parse is replaced: holding every answer back on it would be worse.
   */
  private async load(session: string): Promise<Line[]> {
    this.sessions.add(session);
    const text = await this.host.read(this.path(session));
    let lines: Line[] = [];
    try {
      const parsed = JSON.parse(text ?? "[]");
      if (Array.isArray(parsed)) lines = parsed.filter(isLine);
    } catch {}
    const now = await this.host.now();
    return lines.filter((l) => now - l.at < MAX_AGE_MS);
  }

  /** `load`, or undefined with a log line when the file cannot be read. */
  private async loaded(session: string): Promise<Line[] | undefined> {
    try {
      return await this.load(session);
    } catch (e) {
      this.host.log(`starbridge: could not read the answers sent: ${(e as Error).message}`);
      return undefined;
    }
  }

  /** Writes `session`'s lines; rejects when the write fails. */
  private async save(session: string, lines: Line[]): Promise<void> {
    await this.host.write(this.path(session), JSON.stringify(lines));
  }
}

function isLine(l: unknown): l is Line {
  const x = l as Partial<Line> | null;
  return (
    typeof x?.ack === "string" &&
    typeof x.line === "string" &&
    typeof x.process === "string" &&
    typeof x.at === "number" &&
    typeof x.refused === "number" &&
    (x.agent === undefined || typeof x.agent === "string")
  );
}

/**
 * Whether a live Claude Code process other than `own` runs session `session`, from the
 * `<pid>.json` files Claude Code keeps in `<its config folder>/sessions`; files of processes that
 * ended stay behind, so `runs` checks each pid.
 */
export async function sessionElsewhere(
  session: string,
  own: number,
  fs: { list(dir: string): Promise<{ name: string }[]>; read(path: string): Promise<string> },
  dir: string,
  runs: (pid: number) => Promise<boolean>,
): Promise<boolean> {
  for (const f of await fs.list(dir).catch(() => [])) {
    if (!/^\d+\.json$/.test(f.name) || f.name === `${own}.json`) continue;
    try {
      const s = firstObject(await fs.read(`${dir}/${f.name}`));
      if (
        s?.sessionId === session &&
        typeof s.pid === "number" &&
        s.pid !== own &&
        (await runs(s.pid))
      )
        return true;
    } catch {}
  }
  return false;
}

/**
 * The object a session record starts with. Claude Code rewrites the file without truncating it,
 * so a shorter record leaves the end of the previous one after it, as cli/src/claude.ts reads it.
 */
function firstObject(text: string): { pid?: unknown; sessionId?: unknown } | undefined {
  for (let end = text.indexOf("}"); end !== -1; end = text.indexOf("}", end + 1)) {
    try {
      const value = JSON.parse(text.slice(0, end + 1));
      return value && typeof value === "object" ? value : undefined;
    } catch {}
  }
  return undefined;
}

